#include "umicom/editor/workbench/navigation_stack.h"
int main(void){ UmiEditorWbNavigationStack s; UmiEditorWbEditorLocation a,b; umi_editor_wb_navigation_stack_init(&s); if(umi_editor_wb_editor_location_init(&a,"a.c",1U,1U)!=UMI_STATUS_OK)return 1; if(umi_editor_wb_editor_location_init(&b,"b.c",2U,1U)!=UMI_STATUS_OK)return 2; (void)umi_editor_wb_navigation_stack_push(&s,&a); (void)umi_editor_wb_navigation_stack_push(&s,&b); if(umi_editor_wb_navigation_stack_back(&s)==0)return 3; if(umi_editor_wb_navigation_stack_forward(&s)==0)return 4; return 0; }
